&lt;/ul&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;Base Pay:&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$19.30&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$19.30 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;h2&gt;About DoorDash&lt;/h2&gt;
